console.log("  title:", updated.title);
console.log("  description:", updated.description);
console.log("  priority:", updated.priority);
console.log("  status:", updated.status);
console.log("  dueDate:", updated.dueDate);

// Check if fields are preserved
const descriptionPreserved = updated.description === "Original Description";
const priorityPreserved = updated.priority === 3;
const statusPreserved = updated.status === "pending";
const dueDatePreserved = updated.dueDate === "2025-12-31";

console.log("");
console.log("Field preservation:");
console.log("  description preserved:", descriptionPreserved);
console.log("  priority preserved:", priorityPreserved);
console.log("  status preserved:", statusPreserved);
console.log("  dueDate preserved:", dueDatePreserved);

if (!descriptionPreserved || !priorityPreserved || !statusPreserved || !dueDatePreserved) {
  console.log("\n❌ BUG CONFIRMED: Fields were erased during update!");
  process.exit(1);
} else {
  console.log("\n✅ All fields preserved correctly.");
  process.exit(0);
}

