import { TaskManager } from "./src/task-manager.ts";

const tm = new TaskManager();

// Test 1: Setting dueDate to null should clear it
console.log("Test 1: Setting dueDate to null");
const t1 = tm.createTask({ title: "t1", priority: 1, dueDate: "2025-12-31" });
const u1 = tm.updateTask(t1.id, { dueDate: null });
console.log("  dueDate after update:", u1.dueDate);
console.assert(u1.dueDate === null, "dueDate should be null after setting to null");

// Test 2: Update all fields at once
console.log("Test 2: Update all fields");
const t2 = tm.createTask({ title: "t2", priority: 1, description: "old" });
const u2 = tm.updateTask(t2.id, { title: "new", description: "new desc", priority: 5, status: "completed" });
console.assert(u2.title === "new", "title should be updated");
console.assert(u2.description === "new desc", "description should be updated");
console.assert(u2.priority === 5, "priority should be updated");
console.assert(u2.status === "completed", "status should be updated");

// Test 3: Partial update with multiple fields
console.log("Test 3: Partial update with multiple fields");
const t3 = tm.createTask({ title: "t3", priority: 1, description: "keep", status: "pending" });
const u3 = tm.updateTask(t3.id, { title: "updated", status: "completed" });
console.assert(u3.title === "updated", "title should be updated");
console.assert(u3.description === "keep", "description should be preserved");
console.assert(u3.priority === 1, "priority should be preserved");
console.assert(u3.status === "completed", "status should be updated");

// Test 4: Update with empty object (should change nothing except updatedAt)
console.log("Test 4: Update with empty object");
const t4 = tm.createTask({ title: "t4", priority: 2, description: "keep" });
const u4 = tm.updateTask(t4.id, {});
console.assert(u4.title === "t4", "title should be preserved");
console.assert(u4.description === "keep", "description should be preserved");
console.assert(u4.priority === 2, "priority should be preserved");

console.log("\n✅ All edge case tests passed!");
